. (Join-Path $PSScriptRoot '..\lib\environment.ps1')
. (Join-Path $PSScriptRoot '..\lib\processes.ps1')
$mode=if(Test-Path (Join-Path $script:V4Root 'runtime\active-mode')){(Get-Content (Join-Path $script:V4Root 'runtime\active-mode') -Raw).Trim()}else{'none'};Write-Portal "Mode: $mode"
$compose=docker compose -f $script:ComposeFile ps --format json|ConvertFrom-Json
foreach($service in 'database','phpmyadmin','database-preview','deployment-preview'){ $row=$compose|Where-Object service -eq $service;if($row){Write-Portal "$service container: $($row.State)"} }
if($mode -eq 'deployment-preview'){try{$h=Invoke-WebRequest http://127.0.0.1:8184/ -UseBasicParsing -TimeoutSec 3;Write-Portal "Apache/frontend: healthy ($($h.StatusCode)) http://127.0.0.1:8184"}catch{Write-Portal 'Apache/frontend: unhealthy'};try{$a=Invoke-WebRequest http://127.0.0.1:8184/api/v1/health -UseBasicParsing -TimeoutSec 3;Write-Portal "API health: healthy ($($a.StatusCode))"}catch{Write-Portal 'API health: unhealthy'};Write-Portal 'Database: dnd_portal_v4_preview';Write-Portal 'phpMyAdmin: http://127.0.0.1:8096';Write-Portal "ZIP SHA256: $((Get-FileHash (Join-Path $script:V4Root 'release\dnd-portal-v4-htdocs.zip')).Hash)"}
elseif($mode -eq 'development'){foreach($name in 'backend-development','frontend-development'){$f=Join-Path $script:V4Root "runtime\$name.pid";if(Test-Path $f){$id=[int](Get-Content $f);$running=Get-Process -Id $id -ErrorAction SilentlyContinue;if($running){Write-Portal "${name}: running PID $id"}else{Write-Portal "${name}: stopped (stale PID $id)"}}else{Write-Portal "${name}: stopped"}};try{$a=Invoke-WebRequest http://127.0.0.1:8110/api/v1/health -UseBasicParsing -TimeoutSec 3;Write-Portal "Backend health: healthy ($($a.StatusCode)) http://127.0.0.1:8110"}catch{Write-Portal 'Backend health: unhealthy'};try{$f=Invoke-WebRequest http://127.0.0.1:5174/ -UseBasicParsing -TimeoutSec 3;Write-Portal "Frontend health: healthy ($($f.StatusCode)) http://127.0.0.1:5174"}catch{Write-Portal 'Frontend health: unhealthy'};try{$p=Invoke-WebRequest http://127.0.0.1:8096/ -UseBasicParsing -TimeoutSec 3;if($p.StatusCode -eq 200){Write-Portal "phpMyAdmin health: healthy ($($p.StatusCode)) http://127.0.0.1:8096"}else{Write-Portal "phpMyAdmin health: unhealthy ($($p.StatusCode))"}}catch{Write-Portal 'phpMyAdmin health: unhealthy'};Write-Portal 'Database health: verified through backend PDO health check';Write-Portal 'Database: dnd_portal_v4_development / 127.0.0.1:3310'}
